function handleShopping(id){let x=state.shopping.find(e=>e.id===id);if(!x)return;modal('نتيجة التسوق: '+x.title,`<form class="stack-fields">${field('النتيجة',`<select name="status" id="shoppingStatus"><option value="purchased" ${x.status==='purchased'?'selected':''}>تم الشراء</option><option value="postponed" ${x.status==='postponed'?'selected':''}>تأجيل الشراء</option><option value="skipped" ${x.status==='skipped'?'selected':''}>إتمام دون شراء</option><option value="" ${!x.status?'selected':''}>لم تتم بعد</option></select>`)}<div id="buyInputs" class="stack-fields">${field('سعر الشراء',numberInput('amount',x.amount||0))}${field('من أي محفظة دُفع؟',walletSelect('wallet',x.wallet||'syp'))}</div><div id="noBuyInputs">${field('سبب التأجيل / عدم الشراء',`<textarea name="reason" placeholder="اكتب ما حصل">${q(x.reason||'')}</textarea>`)}</div>${fActions('حفظ حالة التسوق')}</form>`,fd=>{let status=val(fd,'status');if(['postponed','skipped'].includes(status)&&!val(fd,'reason')){toast('اكتب سبب التأجيل أو عدم الشراء',true);return false}let amount=intVal(fd,'amount'),wallet=val(fd,'wallet');if(status==='purchased'&&amount<=0){toast('أدخل مبلغ الشراء',true);return false}if(x.transactionId){state.finance=state.finance.filter(t=>t.id!==x.transactionId);x.transactionId=null}x.status=status;x.amount=status==='purchased'?amount:0;x.wallet=wallet;x.reason=val(fd,'reason');if(status==='purchased'){const t={id:uid(),type:'expense',amount,wallet,date:x.date,description:'شراء: '+x.title,created:Date.now(),originShopping:id};state.finance.push(t);x.transactionId=t.id}save();render();if(status)sound('complete');return true});const update=()=>{let b=$('#shoppingStatus')?.value;$('#buyInputs').hidden=b!=='purchased';$('#noBuyInputs').hidden=b==='purchased'||b===''};$('#shoppingStatus').addEventListener('change',update);update()}
function fileToSmallData(file){return new Promise((resolve,reject)=>{if(!file)return resolve(null);if(!file.type.startsWith('image/'))return reject(Error('يرجى استخدام صورة فقط'));if(file.size>12*1024*1024)return reject(Error('الصورة أكبر من 12 ميغابايت'));const rd=new FileReader();rd.onerror=reject;rd.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{let max=1100,scale=Math.min(1,max/Math.max(img.width,img.height)),can=document.createElement('canvas');can.width=Math.round(img.width*scale);can.height=Math.round(img.height*scale);let ctx=can.getContext('2d');ctx.drawImage(img,0,0,can.width,can.height);resolve(can.toDataURL('image/jpeg',.73))};img.src=rd.result};rd.readAsDataURL(file)})}
function dueSection(type,title,entry){const data=entry||{};return `<div class="card soft"><label class="switchline"><input type="checkbox" name="${type}Enabled" ${data.title?'checked':''}> إضافة ${title}</label><div class="stack-fields" id="section-${type}">${field('العنوان / المطلوب',`<input name="${type}Title" value="${q(data.title||'')}" placeholder="${title}">`)}<div class="field-grid">${field('اليوم والتاريخ',`<input type="date" name="${type}Due" value="${q(data.due||'')}">`)}${type==='project'?field('المدة المحددة (أيام)',`<input type="number" name="${type}Duration" min="0" value="${q(data.duration||0)}">`):'<div></div>'}</div>${type==='study'?field('الموضوعات الداخلة / المطلوب',`<textarea name="studyScope" placeholder="ما المواد الداخلة؟">${q(data.scope||'')}</textarea>`):''}${type==='homework'?`<div class="attachment"><div>صورة الواجب — اختر أو اسحب صورة إلى المربع</div><div class="item-actions" style="justify-content:center"><button type="button" class="btn small" id="cameraTrigger">📷 التقاط صورة</button><label class="btn small ghost" style="margin:0;cursor:pointer">اختيار من المعرض<input type="file" id="homeworkImage" name="homeworkImage" accept="image/*" style="display:none"></label></div><input type="file" id="homeworkCamera" accept="image/*" capture="environment" hidden><div id="homeworkImagePreview">${data.image?`<img src="${data.image}" alt="صورة الواجب الحالية">`:''}</div></div>`:''}</div></div>`}
function attendance(id){const lec=state.lectures.find(l=>l.id===id);if(!lec)return;const log=getLog('lectureLogs',activeDay,id);modal('حضور محاضرة: '+lec.title,`<form class="stack-fields"><div class="info-box">${displayDate(activeDay)} · ${q(lec.time)} · قاعة ${q(lec.room||'غير محددة')}</div>${field('الحالة',`<select name="attendance" id="attendanceChoice"><option value="" ${!log.attendance?'selected':''}>لم يحدد</option><option value="present" ${log.attendance==='present'?'selected':''}>حضور</option><option value="absent" ${log.attendance==='absent'?'selected':''}>غياب</option></select>`)}<div id="absentFields">${field('سبب الغياب',`<textarea name="reason" placeholder="سبب الغياب">${q(log.reason||'')}</textarea>`)}</div><div id="presentFields" class="stack-fields">${field('موضوع المحاضرة',`<textarea name="topic" placeholder="موضوع محاضرة اليوم">${q(log.topic||'')}</textarea>`)}${dueSection('homework','واجب',log.homework)}${dueSection('project','مشروع',log.project)}${dueSection('study','مذاكرة',log.study)}</div>${fActions('حفظ سجل المحاضرة')}</form>`,async(fd,form)=>{const attendance=val(fd,'attendance'),reason=val(fd,'reason');if(attendance==='absent'&&!reason){toast('أدخل سبب الغياب',true);return false}const data={attendance,reason:attendance==='absent'?reason:'',topic:attendance==='present'?val(fd,'topic'):''};if(attendance==='present'){for(const type of ['homework','project','study']){if(fd.get(type+'Enabled')){const existing=log[type]||{},title=val(fd,type+'Title'),due=val(fd,type+'Due');if(!title||!due){toast('أدخل عنوان وموعد '+type,true);return false}data[type]={...existing,title,due,...(type==='project'?{duration:intVal(fd,'projectDuration')}:{}),...(type==='study'?{scope:val(fd,'studyScope')}:{} )};if(type==='homework'){const img=fd.get('homeworkImage');if(img?.size){try{data.homework.image=await fileToSmallData(img)}catch(err){toast(err.message,true);return false}}}}else data[type]=null}}
setLog('lectureLogs',activeDay,id,data);if(attendance==='present'&&!log.attendance)sound('complete');toast('حُفظ سجل المحاضرة');checkReminders();return true});const sync=()=>{$('#presentFields').hidden=$('#attendanceChoice').value!=='present';$('#absentFields').hidden=$('#attendanceChoice').value!=='absent'};$('#attendanceChoice').addEventListener('change',sync);sync();['homework','project','study'].forEach(t=>{const input=$(`[name="${t}Enabled"]`),section=$(`#section-${t}`);if(input){const syncSec=()=>section.hidden=!input.checked;input.addEventListener('change',syncSec);syncSec()}});const area=$('.attachment');if(area){area.addEventListener('dragover',e=>{e.preventDefault();area.style.borderColor='#65dfc1'});area.addEventListener('dragleave',()=>area.style.borderColor='');area.addEventListener('drop',e=>{e.preventDefault();area.style.borderColor='';const file=e.dataTransfer.files?.[0];if(file){const dt=new DataTransfer();dt.items.add(file);$('#homeworkImage').files=dt.files;previewHomework(file)}});$('#homeworkImage')?.addEventListener('change',e=>previewHomework(e.target.files[0]));$('#cameraTrigger')?.addEventListener('click',()=>$('#homeworkCamera')?.click());$('#homeworkCamera')?.addEventListener('change',e=>{const file=e.target.files[0];if(file){const dt=new DataTransfer();dt.items.add(file);$('#homeworkImage').files=dt.files;previewHomework(file)}})}}
