function moneyEdit(id){const old=state.finance.find(t=>t.id===id);modal(old?'تعديل حركة مالية':'إضافة حركة مالية',`<form class="stack-fields">${field('نوع الحركة',`<select name="type" id="moneyType"><option value="expense" ${old?.type==='expense'?'selected':''}>مصروف</option><option value="income" ${old?.type==='income'?'selected':''}>دخل</option><option value="transfer" ${old?.type==='transfer'?'selected':''}>تحويل بين محافظ بنفس العملة</option></select>`)}<div class="field-grid">${field('المبلغ',numberInput('amount',old?.amount||0))}${field('التاريخ',dateInput('date',old?.date||activeDay))}</div>${field('المحفظة',walletSelect('wallet',old?.wallet||'syp'))}<div id="transferField">${field('المحفظة المستقبلة للتحويل',walletSelect('toWallet',old?.toWallet||'shamsSyp'))}</div>${field('وصف الحركة',`<textarea name="description" placeholder="لماذا دخل المبلغ أو خرج؟">${q(old?.description||'')}</textarea>`)}${fActions('حفظ الحركة')}</form>`,fd=>{const type=val(fd,'type'),amount=intVal(fd,'amount'),wallet=val(fd,'wallet'),toWallet=val(fd,'toWallet');if(amount<=0){toast('المبلغ يجب أن يكون أكبر من الصفر',true);return false}if(type==='transfer'&&(wallet===toWallet||WALLETS.find(w=>w.id===wallet)?.unit!==WALLETS.find(w=>w.id===toWallet)?.unit)){toast('يجب التحويل بين محفظتين مختلفتين بنفس العملة',true);return false}const data={id:old?.id||uid(),type,amount,wallet,toWallet:type==='transfer'?toWallet:null,date:val(fd,'date'),description:val(fd,'description'),created:old?.created||Date.now()};if(old){Object.assign(old,data);if(old.originShopping){const s=state.shopping.find(s=>s.id===old.originShopping);if(s){s.amount=amount;s.wallet=wallet;s.date=data.date}}}else state.finance.push(data);save();render();toast('تم حفظ الحركة المالية');return true});const change=()=>$('#transferField').hidden=$('#moneyType').value!=='transfer';$('#moneyType').addEventListener('change',change);change()}
function debtEdit(id){const old=state.debts.find(d=>d.id===id);modal(old?'تعديل مستحقات':'إضافة دائن أو مدين',`<form class="stack-fields">${field('نوع العلاقة',`<select name="kind"><option value="creditor" ${old?.kind==='creditor'?'selected':''}>دائن — مبلغ مطلوب منك للآخرين</option><option value="debtor" ${old?.kind==='debtor'?'selected':''}>مدين — مبلغ مطلوب لك من الآخرين</option></select>`)}${field('اسم الشخص',`<input name="person" required value="${q(old?.person||'')}">`)}<div class="field-grid">${field('المبلغ',numberInput('amount',old?.amount||0))}${field('نوع العملة / المحفظة المرجعية',walletSelect('wallet',old?.wallet||'syp'))}</div>${field('موعد التسوية (اختياري)',`<input type="date" name="due" value="${q(old?.due||'')}">`)}${field('التفاصيل',`<textarea name="note">${q(old?.note||'')}</textarea>`)}${fActions()}</form>`,fd=>{const data={id:old?.id||uid(),kind:val(fd,'kind'),person:val(fd,'person'),amount:intVal(fd,'amount'),wallet:val(fd,'wallet'),due:val(fd,'due'),note:val(fd,'note'),settled:old?.settled||false};if(!data.person||!data.amount){toast('أدخل الاسم والمبلغ',true);return false}old?Object.assign(old,data):state.debts.push(data);save();render();return true})}
function deleteItem(type,id){const map={goal:'goals',task:'tasks',habit:'habits',lecture:'lectures',shopping:'shopping',grade:'announcements',money:'finance',debt:'debts'};const p=map[type];if(!p)return;if(!confirm('هل تريد حذف هذا السجل؟ لا يمكن التراجع دون نسخة احتياطية.'))return;let x=state[p].find(z=>z.id===id);if(type==='shopping'&&x?.transactionId)state.finance=state.finance.filter(t=>t.id!==x.transactionId);if(type==='money'&&x?.originShopping){let s=state.shopping.find(v=>v.id===x.originShopping);if(s){s.status='';s.transactionId=null;s.amount=0}}state[p]=state[p].filter(z=>z.id!==id);save();render();toast('تم حذف السجل')}
function exportData(){const blob=new Blob([JSON.stringify({app:'athar-productivity',exported:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`athar-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('تم إعداد ملف النسخة الاحتياطية')}
async function importData(file){if(!file)return;try{const json=JSON.parse(await file.text());if(json.app!=='athar-productivity'||!json.data||!Array.isArray(json.data.finance))throw Error('صيغة غير صالحة');if(!confirm('ستُستبدل البيانات الحالية بالنسخة المستوردة. هل تريد المتابعة؟'))return;state={...fresh(),...json.data};state.wallets={...fresh().wallets,...state.wallets};save();render();toast('تم استيراد النسخة الاحتياطية')}catch(e){toast('تعذّر استيراد الملف: تحقق من أنه نسخة من تطبيق أثر',true)}}
function changePassword(){modal('تغيير كلمة المرور',`<form class="stack-fields">${field('كلمة المرور الحالية',`<input type="password" name="old" required>`)}${field('كلمة المرور الجديدة',`<input type="password" name="next" minlength="4" required>`)}${field('تأكيد كلمة المرور الجديدة',`<input type="password" name="confirm" minlength="4" required>`)}${fActions('حفظ كلمة المرور')}</form>`,async fd=>{const old=JSON.parse(localStorage.getItem(LOCK)),pass=val(fd,'old'),next=val(fd,'next');if(await sha(old.salt+'|'+pass)!==old.hash){toast('كلمة المرور الحالية غير صحيحة',true);return false}if(next.length<4||next!==val(fd,'confirm')){toast('تحقق من كلمة المرور الجديدة وتأكيدها',true);return false}const salt=uid();localStorage.setItem(LOCK,JSON.stringify({salt,hash:await sha(salt+'|'+next)}));toast('تم تغيير كلمة المرور');return true})}
function toggleDue(key){const arr=key.split('-');const type=arr.pop();const core=arr.join('-');const n=core.lastIndexOf('|');if(n<0)return;const date=core.slice(0,n),id=core.slice(n+1);const old=getLog('lectureLogs',date,id),entry=old[type];if(!entry)return;setLog('lectureLogs',date,id,{[type]:{...entry,completed:!entry.completed}})}
// جميع أزرار التعديل والعمليات من عنصر توجيه مركزي
$('#content').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;render();return}const act=b.dataset.action,id=b.dataset.id;if(!act)return;
if(act.startsWith('add-')){const t=act.slice(4);if(['goal','task','habit','lecture','shopping','grade'].includes(t))return editSimple(t);if(t==='extra')return editExtra();if(t==='money')return moneyEdit();if(t==='debt')return debtEdit()}
if(act.startsWith('edit-')){const t=act.slice(5);if(['goal','task','habit','lecture','shopping','grade'].includes(t))return editSimple(t,id);if(t==='money')return moneyEdit(id);if(t==='debt')return debtEdit(id)}
if(act.startsWith('delete-'))return deleteItem(act.slice(7),id);
switch(act){case 'attendance':return attendance(id);case 'complete':return doneGoal(b.dataset.type,id);case 'habit-complete':return doneHabit(id);case 'extra-complete':return doneGoal('extras',id);case 'buy-shopping':return handleShopping(id);case 'toggle-due':return toggleDue(b.dataset.key);case 'today':activeDay=today();return render();case 'finance-period':finPeriod=b.dataset.value;return render();case 'settle-debt':{const x=state.debts.find(z=>z.id===id);if(x){x.settled=!x.settled;save();render()}return}case 'export':return exportData();case 'import':return $('#importFile').click();case 'change-password':return changePassword();case 'allow-notify':return $('#notifyBtn').click();case 'wipe':if(confirm('تحذير: ستحذف بياناتك المحلية وكل الصور وكلمة المرور. هل لديك نسخة احتياطية؟')&&confirm('تأكيد أخير: هل تريد حذف كل المعلومات نهائياً من هذا المتصفح؟')){localStorage.removeItem(KEY);localStorage.removeItem(LOCK);location.reload()}return;}}
);
$('#content').addEventListener('change',e=>{if(['dashboardDate','editorDay','shopDay'].includes(e.target.id)){activeDay=e.target.value||today();render()}if(e.target.id==='finAnchor'){finAnchor=e.target.value||today();render()}if(e.target.id==='settingsSound'){audioOn=e.target.checked;state.settings.sound=audioOn;save();render()}});
$('#content').addEventListener('submit',e=>{if(e.target.id==='walletSettings'){e.preventDefault();const fd=new FormData(e.target);WALLETS.forEach(w=>state.wallets[w.id]=Number(fd.get(w.id)||0));save();render();toast('تم حفظ الأرصدة الافتتاحية')}});
$('#content').addEventListener('change',e=>{if(e.target.id==='importFile')importData(e.target.files?.[0])});
setInterval(()=>{if(authorized){checkClock();checkReminders()}},60*1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&authorized){checkClock();checkReminders()}});
setupAuth();
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
